/* open-uistacks theme: design tokens for light (:root) and dark (.dark), exposed to Tailwind v4. Import after tailwindcss. */
@theme inline {
  --color-border: var(--border);
  --color-muted: var(--muted);
  --color-danger-solid: var(--danger-solid);
  --color-inverse: var(--inverse);
  --color-inverse-fg: var(--inverse-fg);
  --color-bg: var(--bg);
  --color-danger: var(--danger);
  --color-danger-soft: var(--danger-soft);
  --color-danger-text: var(--danger-text);
  --color-fg: var(--fg);
  --color-fg-muted: var(--fg-muted);
  --color-fg-subtle: var(--fg-subtle);
  --color-raised: var(--raised);
  --color-select: var(--select);
  --color-select-soft: var(--select-soft);
  --color-select-text: var(--select-text);
  --color-subtle: var(--subtle);
  --color-success: var(--success);
  --color-success-soft: var(--success-soft);
  --color-success-text: var(--success-text);
  --color-surface: var(--surface);
  --color-track: var(--track);
  --color-track-strong: var(--track-strong);
  --color-warning: var(--warning);
  --color-warning-soft: var(--warning-soft);
  --color-warning-text: var(--warning-text);
}
:root {
  --border: rgb(0 0 0 / 0.11);
  --muted: #ececee;
  --series-4: #8c59ff;
  --hover-layer: rgb(0 0 0 / 0.04);
  --bg: #ffffff;
  --border-soft: #00000014;
  --danger: #e5484d;
  --danger-soft: #e5484d1a;
  --danger-solid: #dd2631;
  --danger-text: #c42f35;
  --edge: #0000000f;
  --fg: #18181b;
  --fg-muted: #535358;
  --fg-subtle: #67676c;
  --grad-primary: linear-gradient(180deg, #45454b 0%, #2b2b30 100%);
  --inverse: #2b2b30;
  --inverse-fg: #ffffff;
  --on-feature: #ffffff;
  --raised: #ffffff;
  --select: #1e6af1;
  --select-soft: #eef5ff;
  --select-text: #1a52d2;
  --series-1: #1e6af1;
  --series-3: #697385;
  --shadow-btn-primary: 0 0 0 1px #18181b, 0 1px 2px rgb(0 0 0 / 0.2), 0 3px 6px rgb(0 0 0 / 0.12), inset 0 1px 0 rgb(255 255 255 / 0.14);
  --shadow-btn-secondary: 0 0 0 1px rgb(0 0 0 / 0.08), 0 1px 2px rgb(0 0 0 / 0.06), 0 2px 4px rgb(0 0 0 / 0.04), inset 0 1px 0 #ffffff;
  --shadow-card: 0 0 0 1px rgb(0 0 0 / 0.115), 0 1px 2px rgb(0 0 0 / 0.05), 0 4px 12px rgb(0 0 0 / 0.05), 0 12px 24px rgb(0 0 0 / 0.05);
  --shadow-control: 0 0 0 1px var(--border);
  --shadow-hairline: 0 0 0 1px var(--edge);
  --shadow-overlay: 0 0 0 1px var(--edge), 0 1px 1px rgb(0 0 0 / 0.06), 0 3px 3px rgb(0 0 0 / 0.06), 0 6px 6px rgb(0 0 0 / 0.06), 0 12px 12px rgb(0 0 0 / 0.06), 0 24px 24px rgb(0 0 0 / 0.04), 0 16px 48px rgb(0 0 0 / 0.12);
  --subtle: #f4f4f5;
  --success: #12a150;
  --success-soft: #12a1501a;
  --success-text: #0d7a3d;
  --surface: #ffffff;
  --track: #e4e4e7;
  --track-strong: #d4d4d8;
  --warning: #c27803;
  --warning-soft: #c278031a;
  --warning-text: #946200;
}
.dark {
  --border: rgb(255 255 255 / 0.12);
  --muted: #333335;
  --series-4: #b4a0ff;
  --hover-layer: rgb(255 255 255 / 0.06);
  --bg: #1a1a1a;
  --border-soft: #ffffff14;
  --danger: #f06464;
  --danger-soft: #f0646429;
  --danger-solid: #e5484d;
  --danger-text: #f06464;
  --edge: #ffffff14;
  --fg: #ededed;
  --fg-muted: #aaaaaf;
  --fg-subtle: #929292;
  --grad-primary: linear-gradient(180deg, #ffffff 0%, #e9e9ec 100%);
  --inverse: #e9e9ec;
  --inverse-fg: #0a0a0a;
  --raised: #333333;
  --select: #216ef4;
  --select-soft: #152646;
  --select-text: #82adfd;
  --series-1: #4c8dff;
  --series-3: #8b93a3;
  --shadow-btn-primary: 0 0 0 1px #ffffff, 0 1px 2px rgb(0 0 0 / 0.4), inset 0 -1px 0 rgb(0 0 0 / 0.08);
  --shadow-btn-secondary: 0 0 0 1px rgb(255 255 255 / 0.08), 0 1px 2px rgb(0 0 0 / 0.4), inset 0 1px 0 rgb(255 255 255 / 0.06);
  --shadow-card: 0 0 0 1px rgb(255 255 255 / 0.15);
  --shadow-control: 0 0 0 1px var(--border);
  --shadow-overlay: 0 0 0 1px var(--edge), 0 2px 4px rgb(0 0 0 / 0.3), 0 12px 24px rgb(0 0 0 / 0.4), 0 24px 48px rgb(0 0 0 / 0.3);
  --subtle: #1f1f1f;
  --success: #a0efc0;
  --success-soft: #a0efc024;
  --success-text: #a0efc0;
  --surface: #292929;
  --track: #3b3b3b;
  --track-strong: #484848;
  --warning: #f0b232;
  --warning-soft: #ffd24224;
  --warning-text: #f5c35c;
}
@layer base {
  *,
  ::before,
  ::after {
    border-color: var(--border);
  }
}

@custom-variant dark (&:where(.dark, .dark *));
